#include <limits>

bool sumar_comprobado(int a, int b, int& resultado) {
    if (b == 0) {
        resultado = a;
        return true;
    }

    // Completa las comprobaciones y sustituye este resultado provisional.
    resultado = 0;
    return true;
}

int main() {
    int caso = 0;
    if (!(std::cin >> caso)) {
        return 1;
    }

    const int maximo = std::numeric_limits<int>::max();
    const int minimo = std::numeric_limits<int>::lowest();
    int a = 0;
    int b = 0;
    switch (caso) {
    case 1: a = maximo - 2; b = 2; break;
    case 2: a = maximo - 2; b = 3; break;
    case 3: a = minimo + 2; b = -2; break;
    case 4: a = minimo + 2; b = -3; break;
    case 5: a = 0; b = minimo; break;
    case 6: a = -1; b = minimo; break;
    default: return 1;
    }

    int resultado = 17;
    const bool aceptado = sumar_comprobado(a, b, resultado);
    std::cout << "Aceptado=" << aceptado << '\n';
    std::cout << "EsMaximo=" << (resultado == maximo) << '\n';
    std::cout << "EsMinimo=" << (resultado == minimo) << '\n';
    std::cout << "Conservado=" << (resultado == 17) << '\n';
