#include <limits>

bool producto_no_negativo(int a, int b, int& resultado) {
    if (a < 0 || b < 0) {
        return false;
    }
    if (a == 0 || b == 0) {
        resultado = 0;
        return true;
    }

    const int maximo = std::numeric_limits<int>::max();
    if (a > maximo / b) {
        return false;
    }

    resultado = a * b;
    return true;
}

int main() {
    int resultado = 17;
    const bool primero = producto_no_negativo(6, 7, resultado);
    std::cout << primero << ":" << resultado << '\n';

    const int maximo = std::numeric_limits<int>::max();
    const bool segundo = producto_no_negativo(maximo, 2, resultado);
    std::cout << segundo << ":" << resultado;
    return 0;
}
